use shop
db.customers.drop()
const docs = []
for (let i = 1; i <= 10000; i++) {
  docs.push({
    name: `Customer ${i}`,
    email: `user${i}@example.com`,
    city: ['Lisbon', 'Porto', 'Faro'][i % 3],
    loyaltyPoints: i % 500
  })
}
db.customers.insertMany(docs).acknowledged
db.customers.countDocuments()

const before = db.customers.find({ email: 'user5000@example.com' }).explain('executionStats')
before.queryPlanner.winningPlan
before.executionStats.totalDocsExamined

